import { StyleSheet } from 'react-native';

const styles = StyleSheet.create({   
    listText: {
        fontSize: 19,
        color: '#fff',
        backgroundColor: '#fff',
        padding: 5,
        margin: 5,
        borderRadius: 10,
    },

    load: {
        backgroundColor: '#333',
        padding: 5,
        paddingHorizontal:12,
        margin: 5,
        borderRadius: 10,
    },
});
export { styles };
